baselines.baseline:
(Select (Case When Not Exists (Select *  
From Customers As t0 
Where Not t0.ContactName StartsWith 'a' 
) Then True Else False) As value 
)

(Select (Case When Exists (Select *  
From Customers As t0 
) Then True Else False) As value 
)

(Select t0.OrderID, t0.ProductID, t0.Id 
From Order Details As t0 
Where Exists (Select *  
From Orders As t1 
Where (Exists (Select *  
From Customers As t2 
Where (t2.ContactName StartsWith 'xxx' And t2.CustomerID Equals t1.CustomerID) 
) And t1.OrderID Equals t0.OrderID) 
) 
)

(Select (Case When 'ALFKI' IsIn (Select t0.CustomerID 
From Customers As t0 
) Then True Else False) As value 
)

(Select t0.City, t0.CompanyName, t0.ContactName, t0.Country, t0.CustomerID, t0.Phone 
From Customers As t0 
Where t0.CustomerID IsIn {  } 
)

(Select t0.City, t0.CompanyName, t0.ContactName, t0.Country, t0.CustomerID, t0.Phone 
From Customers As t0 
Where t0.CustomerID IsIn { 'ABCDE', 'ALFKI' } 
)

(Select t0.City, t0.CompanyName, t0.ContactName, t0.Country, t0.CustomerID, t0.Phone 
From Customers As t0 
Where t0.CustomerID IsIn (Select t1.CustomerID 
From Orders As t1 
) 
)

(Select Count(All) 
From Orders As t0 
